// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/catalog/insurers", wrapper.ListInsurers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/catalog/insurers", wrapper.CreateInsurer)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/catalog/insurers/{id}", wrapper.UpdateInsurer)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/catalog/lines-of-business", wrapper.ListLinesOfBusiness)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/catalog/lines-of-business", wrapper.CreateLineOfBusiness)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/catalog/lines-of-business/{id}", wrapper.UpdateLineOfBusiness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/catalog/products", wrapper.ListProducts)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/catalog/products", wrapper.CreateProduct)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/catalog/products/{id}", wrapper.UpdateProduct)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/catalog/risk-schemas", wrapper.ListRiskSchemas)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/catalog/commission-agreements", wrapper.ListCommissionAgreements)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/catalog/commission-agreements", wrapper.CreateCommissionAgreement)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/catalog/commission-agreements/{id}", wrapper.UpdateCommissionAgreement)
	})

	return r
}

